content:
{{#ErrorDetails}}
[
		{
			"type": "divider"
		},
		{
			"type": "header",
			"text": {
				"type": "plain_text",
				"text": "🚨 Bright Data - Automation System Alert",
				"emoji": true
			}
		},
		{
			"type": "section",
			"text": {
				"type": "mrkdwn",
				"text": "⚠️ *An error has been detected in the automation system*"
			}
		},
		{
			"type": "divider"
		},
		{
			"type": "section",
			"text": {
				"type": "mrkdwn",
				"text": "*Recipe:* `{{process_name}}`\n*Status:* 🔴 *Failed*"
			}
		},
		{
			"type": "divider"
		},
		{
			"type": "section",
			"text": {
				"type": "mrkdwn",
				"text": "📊 *Error Details*"
			}
		},
		{
			"type": "section",
			"fields": [
				{
					"type": "mrkdwn",
					"text": "*🕐 Timestamp*\n`{{timestamp}}`"
				},
				{
					"type": "mrkdwn",
					"text": "*🌍 Environment*\n`{{environment}}`"
				},
				{
					"type": "mrkdwn",
					"text": "*📦 Parent Process*\n`{{parent_process_name}}`"
				},
				{
					"type": "mrkdwn",
					"text": "*⚙️ Process*\n`{{process_name}}`"
				},
				{
					"type": "mrkdwn",
					"text": "*❌ Error Type*\n`{{error_type}}`"
				},
				{
					"type": "mrkdwn",
					"text": "*👤 Manager*\n`{{automation_manager}}`"
				}
			]
		},
		{
			"type": "section",
			"text": {
				"type": "mrkdwn",
				"text": "*💬 Error Message*"
			}
		},
		{
			"type": "section",
			"text": {
				"type": "mrkdwn",
				"text": "```{{error_message}}```"
			}
		},
		{
			"type": "divider"
		},
		{
			"type": "section",
			"text": {
				"type": "mrkdwn",
				"text": "🔗 *Quick Actions*"
			}
		},
		{
			"type": "actions",
			"elements": [

				{
					"type": "button",
					"text": {
						"type": "plain_text",
						"text": "📋 View Logs",
						"emoji": true
					},
					"style": "danger",
					"url": "{{job_url}}"
				}
			]
		},
		{
			"type": "divider"
		},
		{
			"type": "context",
			"elements": [
				{
					"type": "mrkdwn",
					"text": "💡 *Need Help?* Contact `{{automation_manager}}` or email automation@brightdata.com"
				}
			]
		},
		{
			"type": "context",
			"elements": [
				{
					"type": "mrkdwn",
					"text": "⚡ _Automated alert from Bright Data Integration System_ • <https://brightdata.com|brightdata.com>"
				}
			]
		},
                      {
			"type": "context_actions",
			"elements": [
				{
					"type": "feedback_buttons",
					"action_id": "feedback",
					"positive_button": {
						"text": {
							"type": "plain_text",
							"text": "Good Response"
						},
						"value": "positive"
					},
					"negative_button": {
						"text": {
							"type": "plain_text",
							"text": "Bad Response"
						},
						"value": "negative"
					}
				},
				{
					"type": "icon_button",
					"action_id": "remove",
					"icon": "trash",
					"text": {
						"type": "plain_text",
						"text": "Remove"
					}
				}
			]
		},
		{
			"type": "divider"
		}
	]
{{/ErrorDetails}}
